package com.focusflow.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="goal_items") public class GoalItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String clientId; private String title; private Integer targetMinutes; private Integer progressMinutes; private LocalDateTime deadline; public GoalItem(){} public Long getId(){return id;} public String getClientId(){return clientId;} public void setClientId(String v){clientId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public Integer getTargetMinutes(){return targetMinutes;} public void setTargetMinutes(Integer v){targetMinutes=v;} public Integer getProgressMinutes(){return progressMinutes;} public void setProgressMinutes(Integer v){progressMinutes=v;} public LocalDateTime getDeadline(){return deadline;} public void setDeadline(LocalDateTime v){deadline=v;} }
